// OLL and PLL cases for the 3×3. Each case has up to 4 algorithms, most popular first (the first
// is the standard). Generated by scripts/build-algs.ts from scripts/algs-source.txt
// (speedcubedb.com lists), and checked by `npm run check:algs`: every algorithm keeps the first
// two layers solved, keeps the top on top (y turns are fine), solves the same case as the others
// listed for it, and each set covers every case exactly once.
// Case diagrams are drawn from the algorithm, so they show the cube as held for that algorithm.

import { OLL2, PBL } from "./algs2x2.ts";

// 3×3: OLL, PLL (CFOP last layer). 2×2: OLL2, PBL (Ortega). OLL2 is shown as "OLL" on the 2×2 tab.
export type AlgSet = "OLL" | "PLL" | "OLL2" | "PBL";
export type AlgPuzzle = "3x3" | "2x2";
export const SETS: Record<AlgPuzzle, AlgSet[]> = { "3x3": ["OLL", "PLL"], "2x2": ["OLL2", "PBL"] };
export const SET_LABEL: Record<AlgSet, string> = { OLL: "OLL", PLL: "PLL", OLL2: "OLL", PBL: "PBL" };
export const puzzleOf = (set: AlgSet): AlgPuzzle => (set === "OLL2" || set === "PBL" ? "2x2" : "3x3");
export const isAlgSet = (v: unknown): v is AlgSet => v === "OLL" || v === "PLL" || v === "OLL2" || v === "PBL";
export interface AlgCase { set: AlgSet; id: string; name: string; group: string; algs: string[] }

const oll = (n: number, group: string, algs: string[]): AlgCase =>
  ({ set: "OLL", id: `oll-${n}`, name: `OLL ${n}`, group, algs });
const pll = (name: string, group: string, algs: string[]): AlgCase =>
  ({ set: "PLL", id: `pll-${name.toLowerCase()}`, name: `${name} perm`, group, algs });

