export const ALGS: Record<AlgSet, AlgCase[]> = { OLL, PLL, OLL2, PBL };

// Setup: the moves that turn a solved cube into the case (the algorithm reversed), done holding the
// cube the same way as when solving it. Checked against the cube model by `npm run check:algs`.
export function setupFor(alg: string): string {
  return alg.trim().split(/\s+/).reverse().map(m => {
    if (m.endsWith("2'") || m.endsWith("2")) return m.replace(/'$/, "");
    return m.endsWith("'") ? m.slice(0, -1) : `${m}'`;
  }).join(" ");
}
